```c
#include <stdio.h>

// Define the Haar wavelet filters
void haar_wavelet_filters(float *low_pass, float *high_pass) {
    *low_pass = 1.0 / sqrt(2.0);
    *high_pass = 1.0 / sqrt(2.0);
}

int main() {
    float low_pass_filter;
    float high_pass_filter;

    // Initialize the Haar wavelet filters
    haar_wavelet_filters(&low_pass_filter, &high_pass_filter);

    // Print the filters
    printf("Low-pass filter coefficient: %f\n", low_pass_filter);
    printf("High-pass filter coefficient: %f\n", high_pass_filter);

    return 0;
}
```

